def aside_news(extra=''):
    nl = (f'<div style="padding: 20px 22px 22px; border-radius: 14px; {CARD}; display: flex; flex-direction: column; align-items: flex-start; gap: 9px">{h3("Newsletter", 19)}'
          f'<p style="margin: 0; font-size: 13.6px; line-height: 1.45; color: {INK}">News, events and programs, sent by email.</p>'
          f'{btn("Sign Up", NEWSLETTER_URL, "outline", "mail", True, "md", "margin-top: 4px")}</div>')
    return f'<aside style="flex: 1 1 300px; max-width: 400px; min-width: 0; display: flex; flex-direction: column; gap: 18px">{follow_card()}{extra}{nl}</aside>'


def nl_band(sub='Get our news, events and programs by email. Sign up on our newsletter page.'):
    """The newsletter band. lib.newsletter() once it has no dead button; until then the same band with a sign-up link."""
    band = newsletter(sub)
    if '<button' not in band:
        return band
    right = (f'<a class="btn bp" href="{NEWSLETTER_URL}" style="display: inline-flex; align-items: center; justify-content: center; gap: 11px; min-height: 42px; padding: 0 22px; '
             f'border-radius: 9px; border: 1px solid #C8A15A; background: linear-gradient(180deg, #20502B 0%, #133419 100%); color: #FFFFFF; font-size: 13.6px; font-weight: 600; '
             f'line-height: 1.2; text-align: center; text-decoration: none; box-shadow: 0 2px 6px rgba(40, 20, 10, 0.3)">'
             f'{ico("mail", 17, "#FFFFFF", 1.8)}<span>Sign up for the newsletter</span>{ico("external", 15, "#FFFFFF", 2)}</a>')
    return rust_band('mail', 'Stay Connected with IIPCT', sub, right)


# ------------------------------------------------------------------ one Facebook post
URL = re.compile(r'https?://[^\s<]+')
EMAIL = re.compile(r'[\w.+-]+@[\w-]+(?:\.[\w-]+)+')


def _link(m):
    url = m.group(0).rstrip('.,)')
    tail = m.group(0)[len(url):]
    bare = url.split('://', 1)[1].rstrip('/')
    label = bare if len(bare) <= 40 else bare.split('/', 1)[0] + '/…'
    return f'<a href="{url}" style="overflow-wrap: anywhere">{label}</a>{tail}'


def _mail(m):
    e = m.group(0).rstrip('.')
    return f'<a href="mailto:{e}" style="overflow-wrap: anywhere">{e}</a>' + m.group(0)[len(e):]


def rich(line):
    t = html.escape(line, quote=False)
    t = URL.sub(_link, t)
    parts = re.split(r'(<a [^>]*>.*?</a>)', t)       # do not touch the links just made
    return ''.join(p if p.startswith('<a ') else EMAIL.sub(_mail, p) for p in parts)


def paras_html(paras):
    return ''.join(f'<p style="margin: 0; font-size: 14.4px; line-height: 1.55; color: {INK}">' + '<br class="k">'.join(rich(l) for l in pl) + '</p>' for pl in paras)


def update(u):
    size = lambda ps: sum(len(' '.join(pl)) for pl in ps)
    vis, rest = u['paras'], []
    if size(u['paras']) > 480 and len(u['paras']) > 1:
        vis, n = [], 0
        for pl in u['paras']:
            vis.append(pl); n += len(' '.join(pl))
            if n >= 220: break
        rest = u['paras'][len(vis):]
        if size(rest) < 140: vis, rest = u['paras'], []
    body = paras_html(vis)
    if rest:
        body += (f'<details style="display: flex; flex-direction: column"><summary style="display: inline-flex; align-items: center; gap: 8px; min-height: 40px; cursor: pointer; '
                 f'font-size: 14px; font-weight: 600; color: {RUST}"><span style="text-decoration: underline; text-underline-offset: 4px">Read the full post</span></summary>'
                 f'<div style="display: flex; flex-direction: column; gap: 10px; padding-top: 4px">{paras_html(rest)}</div></details>')
    if u['note']:
        body += (f'<p style="margin: 0; display: flex; align-items: flex-start; gap: 9px; padding: 9px 12px; border-radius: 10px; background: #F6EACD; border: 1px solid #DCC28C; '
                 f'font-size: 13.6px; line-height: 1.45; color: #3B2E12">{ico("info", 17, "#7A5A14", 1.9, "margin-top: 1px")}<span>{u["note"]}</span></p>')
    links = ''
    if u['i'] in EVENT_ANCHOR:
        links += tlink('Event details', f'events-programs.html#{EVENT_ANCHOR[u["i"]]}', 'arrow', 13.6)
    if u['i'] in JOB_LINK:
        links += tlink('See the job posting', JOB_LINK[u['i']], 'arrow', 13.6) + tlink('Careers at IIPCT', 'Careers.dc.html', 'arrow', 13.6)
    links += tlink('See this post on Facebook', u['fb'], 'arrow', 13.6)
    pic = ''
    if u['img']:
        th, w, h, full, alt, _src = u['img']
        pic = (f'<a href="/_site/{full}" style="flex: 0 0 190px; max-width: 100%; align-self: flex-start; display: block; border-radius: 10px">'
               + photo(th, alt, f'width: 100%; height: auto; border-radius: 10px; border: 1px solid {LINE}', '', w, h) + '</a>')
    head = html.escape(u['head'], quote=False).replace("'", '’')
    return (f'<article id="{u["id"]}" style="scroll-margin-top: 16px; display: flex; flex-wrap: wrap; align-items: flex-start; gap: 16px 24px; padding: 20px 22px; border-radius: 14px; {CARD}">'
            f'{pic}<div style="flex: 1 1 300px; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 10px">'
            f'<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px">{tg(u["cat"], "sage" if u["cat"] in ("Recap", "Award") else "tan" if u["cat"] == "Announcement" else "rust" if u["cat"] == "Health" else "cream")}{meta(dlong(u["date"]))}</div>'
            f'<h4 style="margin: 0; font-family: {SERIF}; font-weight: 700; font-size: 21px; line-height: 1.16; letter-spacing: -0.016em; color: {HEAD}">{head}</h4>'
            f'{body}<div style="display: flex; flex-wrap: wrap; align-items: center; gap: 0 20px">{links}</div></div></article>')


def updates_section():
    months = []
    for u in UPDATES:
        m = u['date'][:7]
        if not months or months[-1][0] != m: months.append((m, []))
        months[-1][1].append(u)
    label = lambda m: f'{MONTHS[int(m[5:]) - 1]} {m[:4]}'
    jump = ''.join(f'<li><a class="bo" href="#m-{m}" style="display: inline-flex; align-items: center; min-height: 40px; padding: 0 14px; border-radius: 999px; background: #FFFDF8; '
                   f'border: 1px solid #C9B691; font-size: 13.4px; font-weight: 600; color: {HEAD}; text-decoration: none; white-space: nowrap">{label(m)}</a></li>' for m, _ in months)
    out = (f'<p style="margin: 0; max-width: 700px; font-size: 14.8px; line-height: 1.55; color: {INK}">Posts from IIPCT’s Facebook page from April to November 2026, newest first, in their own words. '
           f'Older posts could not be collected. Closures and posts shared from other organizations are not repeated here.</p>'
           f'<nav aria-label="Updates by month"><ul style="margin: 0; padding: 0; list-style: none; display: flex; flex-wrap: wrap; gap: 8px">{jump}</ul></nav>')
    for m, us in months:
        out += (f'<div id="m-{m}" style="scroll-margin-top: 16px; display: flex; flex-direction: column; gap: 14px; padding-top: 8px">'
                f'<h3 style="margin: 0; font-family: {SERIF}; font-weight: 700; font-size: 24px; line-height: 1.1; color: {HEAD}">{label(m)}</h3>'
                + ''.join(update(u) for u in us) + '</div>')
    return out


