 {'i': 3, 'id': 'u1806917914774239', 'date': '2026-11-17', 'cat': 'Hiring', 'show': 'careers', 'head': "We're Hiring! Addictions & Mental Health Counsellor", 'paras': [['Tsi Kanonhkhwatsheríyo Indigenous Interprofessional Primary Care Team (IIPCT) is looking for a compassionate and dedicated Addictions & Mental Health Counsellor to join our team!'], ['Location: Shannonville, Ontario', 'Compensation: $32.78 – $40.76 per hour'], ['This position plays an important role in supporting individuals and families experiencing substance use and mental health challenges through culturally grounded, trauma-informed counselling, harm reduction, advocacy and recovery support.'], ['Working alongside our multidisciplinary team and Traditional Healing services, the successful candidate will help support wholistic wellness and access to both traditional and Western approaches to healing.'], ["We're looking for someone with:"], ['Registration as an RSSW, RSW or RP in Ontario'], ['A minimum of 2 years of relevant addictions counselling experience'], ['Experience working with Indigenous individuals, families and communities'], ['A commitment to providing compassionate, culturally safe and person-centred care'], ['Interested in joining our team?'], ['View the full job description and apply online:'], ['https://iipct.bamboohr.com/careers/44'], ['Please share this opportunity with anyone who may be interested!']], 'note': None, 'img': None, 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02AmURcH4sL26pevj5NUt3iXnkjTSikaHZZuURdTP9NvFiLeUeoPkM14ut1DvJENk7l'},
 {'i': 5, 'id': 'u1801559378643426', 'date': '2026-11-13', 'cat': 'Recap', 'show': 'news', 'head': 'Today Is the Day! Battle of the Bowls!', 'paras': [['With World Diabetes Day tomorrow, November 14th, we’re kicking off the conversation about diabetes awareness with some delicious homemade soup!'], ['Join us TODAY from 3:00–6:00 PM at 14 York Road, Shannonville, Unit 4 for our Battle of the Bowls Soup Competition!'], ['Come taste some amazing soups made by members of our community, learn a few diabetes facts along the way, and vote for your favourite!'], ['Which soup will be crowned our Battle of the Bowls Champion?'], ['We can’t wait to see everyone!']], 'note': None, 'img': ('news/2026-11-13-today-is-the-day-battle-of-the-bowls.jpg', 640, 480, 'news/2026-11-13-today-is-the-day-battle-of-the-bowls-full.jpg', 'A whiteboard listing the soups in the Battle of the Bowls competition, with ballot boxes on the table below', 'images/2026-11-13_1420_2.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02SibHuqndhwnu1xX1ZxhtyAC758fxWrLg7qnwbczHqzmSHdMrGtgLNGvzFuUYNHwsl'},
 {'i': 8, 'id': 'u1797789132353784', 'date': '2026-11-10', 'cat': 'Announcement', 'show': 'event', 'head': "Santa's Puzzle Palooza Is Coming! Get Your Team Ready!", 'paras': [['Think your team has what it takes to be the fastest puzzle masters this holiday season? Gather your friends, family, or coworkers and join us for a fun-filled evening of friendly competition, holiday cheer, and prizes!'], ['Event Details:', 'Monday, December 7th, 2026', '6:00 PM – 8:00 PM (Doors open at 5:00 PM)', '14 York Road, Unit 4, Shannonville'], ['Turkey dinner will be available!'], ['How It Works:'], ['Teams of 4 will compete to complete a holiday-themed puzzle the fastest!'], ['Prizes to be won!'], ['At least ONE team member must be an IIPCT rostered patient (have a doctor or nurse practitioner with one of our clinics).'], ['LIMITED SPOTS AVAILABLE!'], ['Registration opens Monday, November 16th at 8:30 AM!'], ['For questions or more information, please contact Allison Loft at allison.loft@iipct.com or 613-827-5178.'], ['Get your team together and see who will be crowned our holiday puzzle champions!']], 'note': None, 'img': ('news/2026-11-10-santa-s-puzzle-palooza-is-coming-get-your-team-r.jpg', 640, 828, 'news/2026-11-10-santa-s-puzzle-palooza-is-coming-get-your-team-r-full.jpg', "Flyer: Santa's Puzzle Palooza Is Coming! Get Your Team Ready!", 'images/2026-11-10_1800_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02TL5uKi5PRsrt5saEo6E5BZ6VRQyVyaAWN3rhWUvKGxLsGd3W7qZVYHQkMUS3ipVgl'},
