 {'i': 13, 'id': 'u1792861182846579', 'date': '2026-11-06', 'cat': 'Announcement', 'show': 'event', 'head': 'Will Planning Presentation – Shannonville', 'paras': [['Planning ahead is an important step in protecting yourself and your loved ones!'], ['Join us for an informative Will Planning Presentation, facilitated by Queen’s Elder Law Clinic.'], ['Learn about the basics of wills and Powers of Attorney, why planning ahead matters, and what costs may be involved. There will also be an opportunity to ask questions!'], ['Monday, November 30, 2026', '3:00 PM – 4:30 PM', '14 York Road, Unit 4, Shannonville'], ['Attend for a chance to WIN!', 'All attendees will be entered into a draw for a Life File Box filled with prizes!'], ['Light refreshments will be provided.'], ['Registration is required!', 'Register here: https://forms.cloud.microsoft/r/7VMrU1rGAS'], ['Please note: This presentation is intended for IIPCT rostered clients and Indigenous community members, both on and off Territory.'], ['For more information, please contact Shelley Loft, Indigenous Lifelong Care Coordinator, at 343-478-0196 ext. 115 or shelley.loft@iipct.com.']], 'note': None, 'img': ('news/2026-11-06-will-planning-presentation-shannonville.jpg', 640, 828, 'news/2026-11-06-will-planning-presentation-shannonville-full.jpg', 'Flyer: Will Planning Presentation – Shannonville', 'images/2026-11-06_1800_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02Usxxojs1KLimGCD6wkTrRoCrkBK1o1PmPQgxNTiA4wz4LLGPbrpiXNWefocFaJzAl'},
 {'i': 17, 'id': 'u1787369566729074', 'date': '2026-11-02', 'cat': 'Announcement', 'show': 'event', 'head': 'Candy Cane Lane Family Dance!', 'paras': [['Get ready for a festive evening of family fun at our Tobacco Awareness Candy Cane Lane Family Dance!'], ['Put on your coziest Christmas pajamas and join us for an evening filled with music, laughter, holiday activities, and memories with your loved ones!'], ['What to Expect:'], ['Music with DJ Reese'], ['Winter crafts'], ['Pizza (while supplies last)'], ['Family photo keepsake'], ['Christmas tree prizes'], ['Smoking trivia and tobacco awareness activities'], ['Friday, November 27', '6:00 PM – 8:00 PM', 'Community Centre – 1807 York Road'], ['Sensory-Friendly Hour: 5:00 PM – 6:00 PM', "We'll be offering a quieter experience with the lights on and music turned down for families who prefer a sensory-friendly environment."], ['Dress Code: Your coziest Christmas pajamas! Bring out the festive prints, holiday slippers, and Christmas accessories!'], ['Please Note:'], ['This is a drug- and alcohol-free event.'], ['All youth must be accompanied by an adult.'], ['Open to MBQ members and on-territory residents only.'], ['For more information, please contact Hannah Hill at chrcwb@mbq-tmt.org.'], ["We can't wait to celebrate the holiday season with you and your family!"]], 'note': None, 'img': ('news/2026-11-02-candy-cane-lane-family-dance.jpg', 640, 853, 'news/2026-11-02-candy-cane-lane-family-dance-full.jpg', 'Flyer: Candy Cane Lane Family Dance!', 'images/2026-11-02_1000_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0cEYMWakrxb7BdDRuRRKNnJVcT8ck2uV9p4Fy5afRJQvjVGns2i39T4douAoXDuSEl'},
