 {'i': 37, 'id': 'u1756977693101595', 'date': '2026-10-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Join Us for Our Harvest Social & Vendor Market in Bancroft!', 'paras': [['Come celebrate the fall season with an evening of traditional foods, an Indigenous vendor market, kids’ crafts, giveaways, special performances, and more!'], ['Friday, October 16', '4:00–8:00 PM', 'Faraday Community Centre', '13 Lower Faraday Rd., Bancroft'], ['Special Guests:', '• 4:00 PM – Bree Paudash, Jingle Dress Dancer', '• 5:00 PM – Shawashkong Ikwe Singers', '• 7:00 PM – Jamie Maracle, Dancer & Singer', 'ALL ARE WELCOME!', 'Free admission – no registration required!'], ['Bring your family and friends, enjoy some delicious food, shop from Indigenous vendors, and spend the evening celebrating community, culture, and the harvest season.'], ['For more information, contact Monica at 343-478-0196 ext. 311 or monica.sears@iipct.com']], 'note': None, 'img': ('news/2026-10-06-join-us-for-our-harvest-social-vendor-market-in.jpg', 640, 828, 'news/2026-10-06-join-us-for-our-harvest-social-vendor-market-in-full.jpg', 'Flyer: Join Us for Our Harvest Social & Vendor Market in Bancroft!', 'images/2026-10-06_1100_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02WwLCn29aBa4FALt2f6CGbVpR76FT2q5LVckB8YNMte9HDwYkFiVgzvkvgR28rxETl'},
 {'i': 38, 'id': 'u1756873263112038', 'date': '2026-10-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Fall Into Harvest with Us!', 'paras': [['Join Tsi Kanonhkhwatsherí:yo Indigenous Interprofessional Primary Care Team for a cozy evening filled with good food, creativity, and community!'], ['Thursday, October 15th', '5:00–7:00 PM', '14 York Road, Unit 4, Shannonville'], ['Come together to celebrate the fall harvest while enjoying some delicious food and creating your very own beaded corn keychain!'], ['Children are welcome to join in the fun and make their own corn keychain too!'], ['Space is limited, so registration is required. Scan the QR code on the poster to register or at the link here https://forms.cloud.microsoft/r/1iZHDkfB8X'], ['We hope to see you there!']], 'note': None, 'img': ('news/2026-10-06-fall-into-harvest-with-us.jpg', 640, 828, 'news/2026-10-06-fall-into-harvest-with-us-full.jpg', 'Flyer: Fall Into Harvest with Us!', 'images/2026-10-06_0911_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0k46EJGAtUhggrHDyvBwXVRPXB5hzirAa2o3jy2thQEcfFXLGrDJbQBh3xamjH5ZJl'},
 {'i': 41, 'id': 'u1749349467197751', 'date': '2026-09-29', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Red Dress Beading Drop-In', 'paras': [['Join us on October 5th as we recognize the National Day of Action for Missing and Murdered Indigenous Women, Girls, and Two-Spirit People.', 'Drop in and create your choice of beaded earrings, a barrette, or a pin featuring a red dress. No beading experience is needed — come learn, create, and spend some time together.', 'Shannonville – 14 York Road, Unit 4', 'October 5th', '4:00–6:00 PM', 'All supplies provided', 'Light refreshments available', 'Open to all Indigenous people and their immediate household members', 'No registration required — just drop in!', 'For more information, contact Allison Loft at 343-478-0196 ext. 213 or allison.loft@iipct.com']], 'note': None, 'img': ('news/2026-09-29-red-dress-beading-drop-in.jpg', 640, 828, 'news/2026-09-29-red-dress-beading-drop-in-full.jpg', 'Flyer: Red Dress Beading Drop-In', 'images/2026-09-29_1606_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02HykMkVhgyyXbF9zMb3MENG6hmhhexg9qAmg6uYw8J3A6KFVKiXSNMLzQ6aAChxeAl'},
 {'i': 45, 'id': 'u1744438974355467', 'date': '2026-09-25', 'cat': 'Health', 'show': 'event-archive', 'head': 'Community Cancer Screenings Are Coming to IIPCT This October!', 'paras': [['If you are without a family doctor or nurse practitioner and are due for cervical cancer screening, appointments are available at our IIPCT locations:'], ['Deseronto – Tuesday, October 6 | 4:30–7:00 p.m.', 'Kingston – Thursday, October 8 | 4:30–7:00 p.m.', 'Tyendinaga – Tuesday, October 13 | 4:30–7:00 p.m.', 'Bancroft – Thursday, October 15 | 4:30–7:00 p.m.'], ['Depending on your eligibility, a mammogram referral or FIT kit may also be offered during your appointment.'], ['Book your appointment: 343-478-0196', 'tracy.keith@iipct.com'], ['Please share with family, friends, and community members who may benefit!']], 'note': None, 'img': ('news/2026-09-25-community-cancer-screenings-are-coming-to-iipct.jpg', 640, 1054, 'news/2026-09-25-community-cancer-screenings-are-coming-to-iipct-full.jpg', 'Flyer: Community Cancer Screenings Are Coming to IIPCT This October!', 'images/2026-09-25_0933_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02kutXxDnrYYBtVQVpRGajuyEMdyTaoscPZX7Fh1vVKiTJgkwkb4cuXpB4QgkP94yYl'},
 {'i': 46, 'id': 'u1742257401240291', 'date': '2026-09-23', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Orange Shirt Day Pin Making – Drop In', 'paras': [['ORANGE SHIRT DAY PIN MAKING - DROP IN TOMORROW!'], ['Join us tomorrow from 9:00-11:00am to create an orange shirt day pin in recognition of the National Day for Truth and Reconciliation.'], ["Already picked up a kit? Bring it with you and we can help you finish it! Didn't get one yet? We still have kits available!"], ['All supplies provided', 'Light refreshments available'], ['We hope to see you there!']], 'note': None, 'img': ('news/2026-09-23-orange-shirt-day-pin-making-drop-in.jpg', 640, 828, 'news/2026-09-23-orange-shirt-day-pin-making-drop-in-full.jpg', 'Flyer: Orange Shirt Day Pin Making – Drop In', 'images/2026-09-23_0957_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0NwByKuRa3XyPjrcPRqZceeyXShqsRu1Hr6gPTcGs3Je4BpY2mRinxRSbGpok1Vtwl'},
 {'i': 53, 'id': 'u1730455082420523', 'date': '2026-09-11', 'cat': 'Award', 'show': 'news', 'head': 'Our Team Took Home Best Team Name/Theme!', 'paras': [['Ruh-Roh…'], ['Our team had SO much fun taking part in the Mocktail Taste Testing for FASD Awareness & Education yesterday!'], ['We went all-in on our Scooby-Doo theme with “Scooby-Doo, Where Are You? At Primary Care!” and served up our Ruh-Roh Remedy mocktail.'], ['And apparently all that meddling paid off… because we took home BEST TEAM NAME/THEME!'], ['A huge thank you to Community Health for putting together such a fun and creative way to bring our community together while raising awareness and education around FASD.'], ['We had an absolute blast dressing up, decorating, serving our mocktails and getting into character.'], ['Zoinks! Until next time!']], 'note': None, 'img': ('news/2026-09-11-our-team-took-home-best-team-name-theme.jpg', 640, 480, 'news/2026-09-11-our-team-took-home-best-team-name-theme-full.jpg', 'Six IIPCT team members in Scooby-Doo costumes posing in a painted cardboard Mystery Machine', 'images/2026-09-11_1052_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid026mQH9cFnYYbvfyCmgB6cFZZPVQ3rKZM55gbVTJLYfd9DsPs8BxAbVLJiyWrA1DKal'},
 {'i': 55, 'id': 'u1727503922715639', 'date': '2026-09-08', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Orange Shirt Day Pin Beading Kits', 'paras': [['In recognition of the National Day for Truth and Reconciliation, we’re offering Orange Shirt Day Pin Beading Kits for IIPCT rostered clients.'], ['Pick up your kit and create your own beaded orange shirt pin to wear on September 30. All supplies and materials needed to complete your pin are included!'], ['Shannonville', 'Monday, September 21 | 2:00–6:00 PM'], ['Bancroft', 'Wednesday, September 23 | 2:00–6:00 PM'], ['Kingston', 'Wednesday, September 23 | 2:00–6:00 PM'], ['Registration is required. Scan the QR code on the poster to register or link here: https://forms.cloud.microsoft/r/uz36MdZw8L'], ['Please note: These kits are intended for IIPCT rostered clients, meaning you have a doctor or nurse practitioner with one of our locations.']], 'note': None, 'img': ('news/2026-09-08-orange-shirt-day-pin-beading-kits.jpg', 640, 828, 'news/2026-09-08-orange-shirt-day-pin-beading-kits-full.jpg', 'Flyer: Orange Shirt Day Pin Beading Kits', 'images/2026-09-08_1602_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02DS1JH41xyJAK5pvPhBHFDkhbXkyF2YvFsPX6R5dZYeac7T7F9ocuNP3ft4H52kCsl'},
 {'i': 56, 'id': 'u1705984661534232', 'date': '2026-08-17', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Nature Retreat – Saturday, September 19, 2026', 'paras': [['We are honoured to partner with the Sunnybrook Pregnancy and Infant Loss Network to offer a Nature Retreat for families who have experienced pregnancy or infant loss.'], ['Held on the Tyendinaga Mohawk Territory, this retreat will provide a supportive space to come together, connect with nature, and honour your journey in a gentle and meaningful way.'], ['Saturday, September 19, 2026', '9:00am-4:00pm', '14 York Road, Unit 4, Shannonville'], ['If you or someone you know may benefit from this retreat, we invite you to learn more and RSVP using the link below:'], ['RSVP:', 'https://www.surveymonkey.com/r/TMTRetreat'], ['For more information, please contact Loralee.mcinroy@sunnybrook.ca or Allison.Loft@iipct.com.']], 'note': None, 'img': ('news/2026-08-17-nature-retreat-saturday-september-19-2026.jpg', 640, 640, 'news/2026-08-17-nature-retreat-saturday-september-19-2026-full.jpg', 'Flyer: Nature Retreat – Saturday, September 19, 2026', 'images/2026-08-17_1450_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid025hG8LHp2JVyUV1rekPRNo8cxmnEh2QsSPhDVbm49CdTE2yjSVNZffQfV5e9VG7Jsl'},
 {'i': 57, 'id': 'u1700092672123431', 'date': '2026-08-11', 'cat': 'Announcement', 'show': 'news', 'head': 'Tsi Kanonhkhwatsherí:yo – 5th Annual General Meeting', 'paras': [['Tsi Kanonhkhwatsherí:yo Indigenous Interprofessional Primary Care Team – 5th Annual General Meeting'], ['We invite you to join us virtually for our 5th Annual General Meeting!'], ['Friday, September 18th, 2026', '9:00 AM – 10:00 AM', 'Virtual via Microsoft Teams'], ['Come hear about the work, growth, and accomplishments of Tsi Kanonhkhwatsherí:yo over the past year.'], ['RSVP by September 14th, 2026 by emailing suzie.sutherland@iipct.com. A Microsoft Teams link will be provided upon RSVP.']], 'note': None, 'img': ('news/2026-08-11-tsi-kanonhkhwatsheri-yo-5th-annual-general-meeti.jpg', 640, 828, 'news/2026-08-11-tsi-kanonhkhwatsheri-yo-5th-annual-general-meeti-full.jpg', 'Flyer: Tsi Kanonhkhwatsherí:yo – 5th Annual General Meeting', 'images/2026-08-11_1500_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0gMAXWBDKcFGH6qdBW8pAGfpN8628KS23a3ysLH1Sk2MdkoMmzesTZUcis1AUHmnLl'},
 {'i': 61, 'id': 'u1695488482583850', 'date': '2026-08-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Advance Care Planning Workshop', 'paras': [['Planning for the future is one of the greatest gifts you can give yourself and your loved ones.'], ['Have you thought about:', "Who would make healthcare decisions if you couldn't?", 'Where your important documents are kept?', 'How to make your wishes known to your family?'], ['Join our Advance Care Planning Workshop presented by our Lifelong Care Coordinator, Shelley Loft, and learn how to prepare for the future with confidence.'], ['Participants will receive a FREE Life File Box featuring:', 'Fireproof & water-resistant protection', 'Lock and key', 'Hanging file folders to keep important documents organized'], ["You'll also receive valuable advance care planning resources, enjoy snacks and light refreshments, and be entered into a draw for a gift card at each workshop location!"], ['Workshop Dates:', 'Shannonville – Wednesday, September 16 | 6:00–8:00 PM', 'Bancroft – Thursday, September 24 | 6:00–8:00 PM (Location to be announced)', 'Kingston – Thursday, October 8 | 6:00–8:00 PM (Location to be announced)'], ['This workshop is open to Indigenous community members both on and off Territory.'], ['Register today: https://forms.cloud.microsoft/r/mEc3bsiRjv']], 'note': None, 'img': ('news/2026-08-06-advance-care-planning-workshop.jpg', 640, 828, 'news/2026-08-06-advance-care-planning-workshop-full.jpg', 'Flyer: Advance Care Planning Workshop', 'images/2026-08-06_1800_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02f8iv8EWXNryzsULXigKjcqeyXi4k5z5sHYRCGwPsP1fnkY14BNosdkjLrTJa3iW5l'},
 {'i': 62, 'id': 'u1695185552614143', 'date': '2026-08-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Back-to-School Teen Locker Packs Are Here!', 'paras': [["Heading into high school this fall? We've got you covered!"], ['The IIPCT Back-to-School Teen Locker Pack is designed to help students in Grades 9–12 start the school year feeling prepared, confident, and supported.'], ['Each locker pack includes:', 'A personal hygiene bag', 'A gift certificate for a haircut', 'Locker organization supplies', 'Tips for managing stress and supporting mental wellness', 'Ideas for balancing school and life'], ['Pick-Up Day: Monday, August 17, 2026', '2:00 PM – 6:00 PM'], ['Pick up at the location most convenient for you:', '• 14 York Rd., Shannonville', '• 730 Front Rd., Kingston', '• 69 Cleak Ave., Bancroft'], ['Open to all IIPCT rostered patients in Grades 9–12.'], ['Register here:', 'https://forms.cloud.microsoft/Pages/ResponsePage.aspx?id=_NhnKjqHr0yNI_laUAK51WoQEskl_iFPmK-yTj0mNglURU1XMUdPUVlURkxSS1FBN05WVDU0NExRTC4u'], ['Questions? Contact Kendra Garvin at 343-478-0196 ext. 107 or kendra.garvin@iipct.com.']], 'note': None, 'img': ('news/2026-08-06-back-to-school-teen-locker-packs-are-here.jpg', 640, 828, 'news/2026-08-06-back-to-school-teen-locker-packs-are-here-full.jpg', 'Flyer: Back-to-School Teen Locker Packs Are Here!', 'images/2026-08-06_1100_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0Zbkpy3tAAmeReWvbMhZ3ft9LEKSGy41Ji4sR9zcB1KiZMszSJ2feAsey4N1ESQN1l'},
 {'i': 65, 'id': 'u1689520899847275', 'date': '2026-07-31', 'cat': 'Recap', 'show': 'news', 'head': 'Sunshine, Golf, and a Whole Lot of Teamwork', 'paras': [['Our Annual Golf Tournament was such a great reminder of how strong (and growing!) our team is. Grateful to work alongside such an amazing group of people — we show up, support each other, and still know how to have a good time!']], 'note': None, 'img': ('news/2026-07-31-sunshine-golf-and-a-whole-lot-of-teamwork.jpg', 640, 379, 'news/2026-07-31-sunshine-golf-and-a-whole-lot-of-teamwork-full.jpg', 'About forty IIPCT team members together in a clubhouse room at the annual golf day', 'images/2026-07-31_1431_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02kQWfQwQaeihKN49DajdbPLuK8W4LgAmDHobm3EBr5vpShntZnu7VkFNxJh6H5vNCl'},
 {'i': 66, 'id': 'u1685748970224468', 'date': '2026-07-27', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Have You Ever Wanted to Learn the Ohen:ton Karihwatehkwen?', 'paras': [['Do you find it challenging to remember each part of the Opening Address?'], ['Join us for a hands-on program where you\'ll explore the meaning and flow of the Ohen:ton Karihwatehkwen—the Haudenosaunee Opening Address, often described as "the words that come before all else." Together, we\'ll create a simple mnemonic (memory aid) to help you remember and carry these important teachings with you.'], ['Mondays, August 10 & 24', '4:00–6:00 PM', '14 York Road, Unit 4, Shannonville'], ["This program is open to the community, and everyone is welcome—whether you're learning the Opening Address for the first time or looking for a new way to strengthen your knowledge."], ['Register here: https://forms.cloud.microsoft/r/gA1JZxp4H3']], 'note': None, 'img': ('news/2026-07-27-have-you-ever-wanted-to-learn-the-ohen-ton-karih.jpg', 640, 828, 'news/2026-07-27-have-you-ever-wanted-to-learn-the-ohen-ton-karih-full.jpg', 'Flyer: Have You Ever Wanted to Learn the Ohen:ton Karihwatehkwen?', 'images/2026-07-27_1715_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0D4VXLMEXWvBQV5MxDYBdLq6PELEEs2oZfMPw7b6uCVW1kLzzcqHrv2EyS7oTtcD6l'},
 {'i': 74, 'id': 'u1655522136580485', 'date': '2026-06-25', 'cat': 'Recap', 'show': 'news', 'head': '4th Annual Strawberry Social – Happening Now in Deseronto', 'paras': [['Join us right now at the Deseronto Community Centre (Arena) 51 Mechanic Street, Deseronto.', '6:00pm social to start!']], 'note': None, 'img': ('news/2026-06-25-4th-annual-strawberry-social-happening-now-in-de.jpg', 640, 480, 'news/2026-06-25-4th-annual-strawberry-social-happening-now-in-de-full.jpg', 'The Deseronto Community Centre hall set up for the Strawberry Social, with vendor tables and people browsing', 'images/2026-06-25_1608_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid032TJw4H1j9MaB5evjAP96cuwJn21bYrqkZ4iVP79wCmDxCAwtZR7HTDBy3aZq5vEMl'},
 {'i': 75, 'id': 'u1654340490031983', 'date': '2026-06-24', 'cat': 'Announcement', 'show': 'news', 'head': 'A New Story on Our Walls', 'paras': [['We are proud to share the beautiful new mural now featured at our Tyendinaga clinic (45 Meadow Drive), created by local Indigenous artist Kory Parkin.'], ['This stunning piece brings together the teachings of the Medicine Wheel and the Four Sacred Medicines, weaving together stories of the seasons, directions, animals, clans, and the natural world. At its centre stands the Great Tree of Peace, rooted on the back of the turtle, reminding us of our connection to Turtle Island, community, healing, and balance.'], ['Every element of this mural carries meaning—from Grandmother Moon and the Sun overhead, to the sacred medicines, clan animals, and Creation Story teachings flowing through the water below. It serves as a powerful reflection of Indigenous knowledge, culture, and the values that guide the care we provide.'], ['A heartfelt thank you to Kory Parkin for sharing his talent and vision with us. We invite everyone visiting our clinic to take a moment to appreciate the teachings and stories held within this incredible artwork.']], 'note': None, 'img': ('news/2026-06-24-a-new-story-on-our-walls.jpg', 640, 540, 'news/2026-06-24-a-new-story-on-our-walls-full.jpg', 'The new mural by Kory Parkin along a hallway at the Tyendinaga clinic: Grandmother Moon, a man in white, a wolf, a turtle and pine trees', 'images/2026-06-24_1144_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02tYQgWfck8mmyqvxR32Pr2C76NFt5BoWM57a2YQ9iDMGmiPigPQnnFeqFLBQAa5enl'},
 {'i': 81, 'id': 'u1638910078241691', 'date': '2026-06-08', 'cat': 'Health', 'show': 'event-archive', 'head': 'Drop-In Kidney Health Screening Clinic – Sharbot Lake', 'paras': [['Join us for a free Kidney Health Screening Clinic for Indigenous individuals and their families.'], ['Wednesday, June 24, 2026', '11:00 AM – 3:00 PM', 'Saint James Major Church Hall', '14608 Highway 38, Sharbot Lake'], ['Kidney disease can develop without symptoms. Screening can help identify concerns early, especially for those living with high blood pressure, diabetes, or a family history of kidney disease.'], ['This Indigenous-led, Indigenous-focused event offers a welcoming and supportive space to learn more about your kidney health and connect with valuable health resources.'], ['Event Highlights:', '• Kidney health screening', '• Traditional crafts', '• Lunch (bring your feast bundles)', '• Draws and raffles', '• Stress reduction techniques', '• Community resources and supports'], ['Look for the Indigenous Interprofessional Primary Care Team (IIPCT) Mobile Van on site!'], ['No appointment necessary—just drop in.'], ['For more information, call 343-322-6800.']], 'note': None, 'img': ('news/2026-06-08-drop-in-kidney-health-screening-clinic-sharbot-l.jpg', 640, 828, 'news/2026-06-08-drop-in-kidney-health-screening-clinic-sharbot-l-full.jpg', 'Flyer: Drop-In Kidney Health Screening Clinic – Sharbot Lake', 'images/2026-06-08_1106_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02tvoBzDLYTEruaZ9EwNPseP2YqEqZXnM8s6w8vbSXXYXi1mRaVgLyTi1ft9BXQfMEl'},
 {'i': 83, 'id': 'u1633865555412810', 'date': '2026-06-03', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Location Update for Our 4th Annual Strawberry Social!', 'paras': [["Please note that this year's Strawberry Social will be held at the Deseronto Community Centre, located at 51 Mechanic Street, Deseronto."], ['Join us on Thursday, June 25, 2026 for an evening of community, culture, and fun!'], ['Social Songs & Dances', 'Free Strawberries & Ice Cream', 'Indigenous Makers Market', "Children's Activities", 'Community Information Booths', 'Soup & Bun available for purchase from the Library'], ['Doors Open: 4:00 PM', 'Social Begins: 6:00 PM', 'Admission is FREE!'], ['We look forward to gathering together and celebrating another wonderful Strawberry Social. Please help us spread the word about our updated location!']], 'note': None, 'img': ('news/2026-06-03-location-update-for-our-4th-annual-strawberry-so.jpg', 640, 828, 'news/2026-06-03-location-update-for-our-4th-annual-strawberry-so-full.jpg', 'Flyer: Location Update for Our 4th Annual Strawberry Social!', 'images/2026-06-03_1000_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid026GMPKhVjbXAjixqdcjCrA3nK5JFgWWeD1FG42yKAi1TuUHoaYr9FyCoZaWGRSnN6l'},
 {'i': 85, 'id': 'u1632774158855283', 'date': '2026-06-02', 'cat': 'Health', 'show': 'news', 'head': 'Do You Struggle with Asthma or COPD?', 'paras': [['Our Respiratory Therapist, Alex, has appointments available this Thursday and Friday in Tyendinaga, with ongoing appointment availability on Thursdays and Fridays moving forward.'], ['Alex provides:', '• Respiratory assessments', '• Treatment planning', '• Ongoing management of breathing and lung disorders', '• Education and support for asthma and COPD', '• Inhaler technique review and optimization', '• Strategies to improve lung health and quality of life'], ["If you or a loved one are living with asthma, COPD, or other breathing concerns, we're here to help."], ['To book an appointment, please contact the Tyendinaga reception desk at 343-478-0196 (Option 1).'], ['Please note this is for IIPCT rostered patients only!']], 'note': None, 'img': ('news/2026-06-02-do-you-struggle-with-asthma-or-copd.jpg', 640, 828, 'news/2026-06-02-do-you-struggle-with-asthma-or-copd-full.jpg', 'Flyer: Do You Struggle with Asthma or COPD?', 'images/2026-06-02_0918_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02sRKUve9xzLS824CThHc2tMZb6NZYqsudSpJdt8EkHAzVpaQFh35Vq5fHEiiLRqsJl'},
 {'i': 87, 'id': 'u1631608655638500', 'date': '2026-06-01', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Family Garden Kits', 'paras': [['PLEASE NOTE THIS PROGRAM IS NOW FULL'], ['Registration is NOW OPEN for our Family Garden Kits!'], ['Looking for a fun way to get your children outdoors, learning, and exploring nature this summer? Our Family Garden Kits are packed with hands-on activities designed to help families grow, learn, and connect together!'], ['Each kit includes:', 'Nature Journal', 'Garden Supplies', 'Herb Seeds & Growing Materials', 'Birdfeeder Craft', 'Nature-Themed Resources', 'Family Activities & More'], ['Open to families with children ages 4+'], ['Registration Opens: Monday, June 1 at 9:00 AM', 'Kit Pick-Up: Monday, July 6 from 2:00–6:00 PM', '14 York Rd., Unit 4, Shannonville'], ['Register here: https://forms.office.com/r/tsE3D0d9me'], ['Priority will be given to IIPCT rostered patients.'], ['Space is limited, so be sure to register early!'], ['For more information, contact Allison at 343-478-0196 ext. 213 or allison.loft@iipct.com.']], 'note': None, 'img': ('news/2026-06-01-family-garden-kits.jpg', 640, 828, 'news/2026-06-01-family-garden-kits-full.jpg', 'Flyer: Family Garden Kits', 'images/2026-06-01_0900_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid064EMJRcuynX8WSKjdD1J5E2kErdbtzc6FGXjttuuJWrLFXGbDDoSJ5QjXQMX1KFil'},
 {'i': 88, 'id': 'u1626953939437305', 'date': '2026-05-27', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Caring for Others Starts with Caring for Yourself', 'paras': [['Join us for a presentation from the Ontario Caregivers Organization on Caregiver Burnout. Learn about the signs of burnout, ways to support your own wellbeing, and resources available for caregivers.'], ['Participants will be entered into a draw for a self-care gift basket', 'Light refreshments will be available'], ['14 York Road, Unit 4', 'Monday, June 29th', '3:30 PM – 4:30 PM'], ['Open to:', '• All rostered IIPCT patients and their household members', '• Self-identifying Indigenous people on and off territory'], ['Register here: https://forms.office.com/Pages/ResponsePage.aspx?id=_NhnKjqHr0yNI_laUAK51TI-QvYbkqdBoXC9LzPA_1pUQjMzTzNYUjBWU1dKNVQ4ODc2U01VQzBBVy4u']], 'note': None, 'img': ('news/2026-05-27-caring-for-others-starts-with-caring-for-yoursel.jpg', 640, 828, 'news/2026-05-27-caring-for-others-starts-with-caring-for-yoursel-full.jpg', 'Flyer: Caring for Others Starts with Caring for Yourself', 'images/2026-05-27_1434_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02GTHeF6j9AcVDteYrMRgcSDgAiuAwBGoBtWqABUzKcAp2EoMqeR8mkrhJ7zi1oggql'},
 {'i': 90, 'id': 'u1624820256317340', 'date': '2026-05-25', 'cat': 'Announcement', 'show': 'news', 'head': 'Welcome, Taryn Krukowski, Nurse Practitioner', 'paras': [['We are excited to welcome Taryn Krukowski to the Tsi Kanonhkhwatsheri:yo Indigenous Interprofessional Primary Care Team!'], ['Taryn is a recent graduate of Laurentian University’s Primary Health Care Nurse Practitioner (PHCNP) program and a proud member of the Algonquin First Nation (817 General List/Sudbury). Prior to relocating to the Deseronto area, Taryn provided primary healthcare services to urban Indigenous communities in Timmins through Misiway Community Health Centre, while also delivering critical care services across Northeastern Ontario through Timmins and District Hospital.'], ['Taryn brings a strong passion for culturally safe, community-centered care, and we are thrilled to have her joining our team at the Deseronto Clinic. Please join us in giving her a warm welcome!']], 'note': None, 'img': ('news/2026-05-25-welcome-taryn-krukowski-nurse-practitioner.jpg', 640, 537, 'news/2026-05-25-welcome-taryn-krukowski-nurse-practitioner-full.jpg', 'Welcome graphic: Meet our new Nurse Practitioner, Taryn Krukowski, joining us at the Deseronto Clinic', 'images/2026-05-25_0913_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02FGvScEGE1PTpQDfENhsJvs814PyFpWY2Zxe86igf79Ti7QGcP762H1LhkM93YDHXl'},
 {'i': 93, 'id': 'u1619385473527485', 'date': '2026-05-19', 'cat': 'Announcement', 'show': 'news', 'head': 'Welcome, Dr. Ryan McConnell, Family Physician', 'paras': [['We are excited to welcome Dr. Ryan McConnell to our growing team at our new Deseronto location!'], ['Dr. McConnell is a proud member of the Mohawks of the Bay of Quinte and a graduate of the Northern Ontario School of Medicine in Sudbury. He completed his residency training through Queen’s University in Belleville and has since been practicing Rural Family Medicine in Tweed.'], ['Having spent most of his life here in Tyendinaga, Dr. McConnell shared that he “couldn’t be more excited to be coming home to serve our community as a Family Physician.”'], ['We are honoured to welcome Dr. McConnell back home and look forward to the care, compassion, and experience he will bring to our patients and communities. Please join us in giving him a warm welcome!']], 'note': None, 'img': ('news/2026-05-19-welcome-dr-ryan-mcconnell-family-physician.jpg', 640, 537, 'news/2026-05-19-welcome-dr-ryan-mcconnell-family-physician-full.jpg', 'Welcome graphic: Meet our new Family Physician, Dr. Ryan McConnell, joining us at the Deseronto Clinic', 'images/2026-05-19_1315_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02qmKjSVk4xAwWnSmXbAyhPZagZsWuQ6QQ5bhxHoHLZk7M8FGMoCFkrMpDaHKBcjUEl'},
 {'i': 94, 'id': 'u1615755563890476', 'date': '2026-05-15', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Outdoor Time Challenge for Kids', 'paras': [['Community Health & IIPCT are challenging kids ages 17 & under to get outside and get active this June!', 'Track how much time you spend active outdoors each day throughout the month of June for a chance to win prizes through ParticipACTION!', 'Why join?', 'Boost energy', 'Improve fitness', 'Reduce stress', 'Help our community work toward becoming Canada’s Most Active Community!', 'Register by May 22nd to receive your activity package at our in-person pick-up on May 25th.', 'Scan the QR code on the poster or register here:', 'https://forms.office.com/pages/responsepage.aspx?id=_NhnKjqHr0yNI_laUAK51XCV-P0EVUtIpioFc1Enu1hUNjY0Q0o0SUlCTzg4VFUxWEJMUkMzMTZNSy4u&route=shorturl', 'Let’s make this summer active, healthy, and fun together!']], 'note': None, 'img': ('news/2026-05-15-outdoor-time-challenge-for-kids.jpg', 640, 828, 'news/2026-05-15-outdoor-time-challenge-for-kids-full.jpg', 'Flyer: Outdoor Time Challenge for Kids', 'images/2026-05-15_1600_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid06YBuJJqDeGEQnBw3w12Tx8CcWCD6QFqjxC2oy4FZWzTrG7kn6n9yDghiC4hXbdiul'},
 {'i': 96, 'id': 'u1615440647255301', 'date': '2026-05-15', 'cat': 'Health', 'show': 'event-archive', 'head': 'Free Skin Cancer Screening Clinics', 'paras': [['Spot something concerning? We’re here to help.'], ['Tsi Kanonhkhwatsherí:yo IIPCT is offering FREE Skin Cancer Screening Clinics with Dr. Rebecca Lys, Family Physician with a focus in Dermatology.'], ['Do you have:', '• A family history of melanoma?', '• A mole, freckle or spot you’re concerned about?', '• Changes in the shape, size or colour of a mole/freckle?'], ['Appointments are available at all three clinic locations:'], ['Kingston Clinic – 730 Front Road', 'June 18 | 9:00 AM – 4:00 PM'], ['Tyendinaga Clinic – 45 Meadow Drive', 'June 26 | 9:30 AM – 3:30 PM'], ['Bancroft Clinic – 69 Cleak Avenue', 'July 9 | 9:30 AM – 3:30 PM'], ['Please note: These clinics are for rostered IIPCT patients only. You must have a Primary Care Provider (Physician or Nurse Practitioner) with IIPCT to book an appointment.'], ['To book your FREE appointment or for more information, please call 343-478-0196 ext. 127.']], 'note': None, 'img': ('news/2026-05-15-free-skin-cancer-screening-clinics.jpg', 640, 828, 'news/2026-05-15-free-skin-cancer-screening-clinics-full.jpg', 'Flyer: Free Skin Cancer Screening Clinics', 'images/2026-05-15_0918_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0nAQVc1qNQwuXUR6FLgbVUJhnPU8PWtDrJH1afPCkGaykUNzunusxD7FX5poHXnG8l'},
 {'i': 97, 'id': 'u1614509960681703', 'date': '2026-05-14', 'cat': 'Health', 'show': 'event-archive', 'head': 'World No Tobacco Day', 'paras': [['Do you smoke or vape? Thinking about cutting back or quitting? You’re not alone—and support is here.'], ['Join us for World No Tobacco Day and get access to tools, resources, and support to help you on your journey. You can also learn about and enroll in STOP (Smoking Treatment for Ontario Patients).'], ['Date: Monday, May 25', 'Time: 2:00pm – 6:00pm', 'Location: 14 York Road, Unit 4, Shannonville'], ['Supplies available while they last!'], ['Taking the first step can be the hardest—but it’s also the most powerful. We’re here to support you every step of the way.'], ['For more information: chrcwb@mbq-tmt.org']], 'note': None, 'img': ('news/2026-05-14-world-no-tobacco-day.jpg', 640, 828, 'news/2026-05-14-world-no-tobacco-day-full.jpg', 'Flyer: World No Tobacco Day', 'images/2026-05-14_1000_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02QPAuEXv6XhNgSHWQizyuSw25KcsUn2PVzmRGWDnWapMkRYU4i1PFVjGFfnv8fuDkl'},
 {'i': 99, 'id': 'u1613531910779508', 'date': '2026-05-13', 'cat': 'Announcement', 'show': 'news', 'head': 'Now Accepting Patients for the Deseronto Clinic Waitlist', 'paras': [['Are you Indigenous and currently without a family doctor or primary care provider? Or are you looking for care closer to home?'], ['The Tsi Kanonhkhwatsheriyo Indigenous Primary Care Team is accepting patients for our Deseronto clinic waitlist!'], ['Our team offers a wholistic approach to care, supporting individuals and families through:', 'Primary Health Care', 'Mental Health Services', 'Traditional Healing', 'Community Development'], ['331 Dundas St., Deseronto, ON'], ['To join the waitlist, please call our Reception Team:', '(343) 478-0196 and press 3', 'Monday to Friday | 8:30 AM – 4:30 PM'], ['Eligibility:', 'Indigenous (Status & Non-Status)'], ['We are committed to providing culturally safe, community-centered care rooted in both Indigenous and mainstream approaches to wellness.'], ['For more information:', '343-478-0196', 'iipct.org']], 'note': 'Our phone menu lists the Deseronto Clinic as option 4 (this post said 3).', 'img': ('news/2026-05-13-now-accepting-patients-for-the-deseronto-clinic.jpg', 640, 828, 'news/2026-05-13-now-accepting-patients-for-the-deseronto-clinic-full.jpg', 'Flyer: Now Accepting Patients for the Deseronto Clinic Waitlist', 'images/2026-05-13_1058_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02kUfLXQSv68nQz4jmd66NEeEzRiEvrpuR7bBwviDkCtJSXieQkCYDMo7Spc1oZPFyl'},
 {'i': 100, 'id': 'u1611795320953167', 'date': '2026-05-11', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Join Our 10K Steps a Day Challenge!', 'paras': [['Join Our 10K Steps A Day Challenge for ParticipACTION!'], ['Community Health & IIPCT are challenging YOU to reach 10,000 steps each day throughout the month of June!'], ['Let’s get moving together while improving our health, boosting energy, reducing stress, and helping our community work towards winning ParticipACTION’s grand prize!'], ['How to Join:', 'Register using the link below by May 22nd', 'Download the StepUp app', 'Track your daily steps throughout June'], ['In-Person Package Pick-Up:', 'May 25th', '2:00 PM – 6:00 PM', '14 York Road, Shannonville'], ['Register here: https://forms.office.com/pages/responsepage.aspx?id=_NhnKjqHr0yNI_laUAK51XCV-P0EVUtIpioFc1Enu1hUMDE3TE43VURFMlFPMjhBVDBIUk9WNzZXUC4u&route=shorturl']], 'note': None, 'img': ('news/2026-05-11-join-our-10k-steps-a-day-challenge.jpg', 640, 828, 'news/2026-05-11-join-our-10k-steps-a-day-challenge-full.jpg', 'Flyer: Join Our 10K Steps a Day Challenge!', 'images/2026-05-11_1534_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid02shNddfjwJDBzSgfvPCjiuK3dzjkFdHXWRSvF8EuB66JCLCLwsHbtBHymeC8ZrkBNl'},
 {'i': 104, 'id': 'u1607821988017167', 'date': '2026-05-07', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Death Doula Training – 2 Day Course', 'paras': [['PLEASE NOTE THIS COURSE IS NOW FULL!'], ['Death Doula Training – 2 Day Course'], ['Join us for a meaningful 2-day Death Doula Training with Diane Boots, End-of-Life Doula. This training offers an opportunity to deepen your understanding of end-of-life care and support individuals and families with compassion and respect.'], ['Choose from two locations:'], ['Kingston', 'Kingston Native Centre and Languages Nest', 'June 1 & 2', '9:00am – 3:00pm'], ['Bancroft', 'Loyalist College of Applied Arts and Technology', 'June 4 & 5', '9:00am – 3:00pm'], ['Breakfast & lunch provided', 'Spots are limited – be sure to indicate your preferred location when registering!'], ['Open to IIPCT registered patients and their household members, as well as self-identifying Indigenous individuals (on and off territory), and non-Indigenous individuals working in healthcare or social services.'], ['Register by scanning the QR code on the poster or click the link here: https://forms.office.com/pages/responsepage.aspx?id=_NhnKjqHr0yNI_laUAK51TI-QvYbkqdBoXC9LzPA_1pUNzhVMFk1UjI0SjVVSFBCWDZYUVJITzMyUC4u&route=shorturl'], ['For more information:', 'Shelley Loft', '343-478-0196 ext. 115', 'shelley.loft@iipct.com']], 'note': None, 'img': ('news/2026-05-07-death-doula-training-2-day-course.jpg', 640, 828, 'news/2026-05-07-death-doula-training-2-day-course-full.jpg', 'Flyer: Death Doula Training – 2 Day Course', 'images/2026-05-07_0933_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0x8TNDyHa7RmXJiZkGo61CxiUCw2uQRGCE5NN8S2DeTEfEDxZazixz5tsQzdtsmW9l'},
 {'i': 105, 'id': 'u1607046464761386', 'date': '2026-05-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': "Let's Talk About Grief", 'paras': [['Grief can look different for everyone—and you don’t have to navigate it alone. Join IIPCT for a 4-week series exploring the many faces of grief in a safe, supportive, and culturally grounded space.'], ['This series will gently guide participants through:', 'Creating a safe space for conversation', 'Understanding how grief impacts us', 'Honouring traditions and renewal', 'Practicing self-care and moving forward'], ['Dates:', '• Tuesday, June 9', '• Tuesday, June 23', '• Tuesday, July 7', '• Tuesday, July 21', 'Time: 6:00pm – 8:00pm', 'Location: 730 Front Road, Kingston'], ['Refreshments will be provided', 'Open to all IIPCT rostered patients'], ['Register by scanning the QR code on the poster or clicking here: https://forms.office.com/r/qzbkmustbp'], ['For more information: 343-478-0196 ext. 214', 'darcy.whalen@iipct.com']], 'note': None, 'img': ('news/2026-05-06-let-s-talk-about-grief.jpg', 640, 828, 'news/2026-05-06-let-s-talk-about-grief-full.jpg', "Flyer: Let's Talk About Grief", 'images/2026-05-06_1400_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0JAzqebLe39vuqe46LW6jt7WsePPXTu2mxtEzcp112LdkDEajd48BmqnASj5WMdVnl'},
 {'i': 107, 'id': 'u1606855861447113', 'date': '2026-05-06', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Youth Mental Health Creativity Workshop (Ages 7-13)', 'paras': [['Join IIPCT for an interactive workshop all about the importance of creativity and youth mental health!'], ['This is a great opportunity for youth to explore creative expression, build confidence, and learn in a supportive environment.'], ['BONUS: Every participant will receive a creativity kit valued at over $200!', '(Kits include items like Bluetooth speakers, carving supplies, clay, writing prompts & more!)'], ['Date: Wednesday, May 27th', 'Time: 6:00pm – 7:30pm', 'Location: 14 York Road, Unit #4, Shannonville'], ['Register by scanning the QR code on the poster or clicking the link here: https://forms.office.com/Pages/ResponsePage.aspx?id=_NhnKjqHr0yNI_laUAK51WCvVwDUyA1BkADmnUHNsh5UMk41OEhGV1JIVTVCSERIV1JQVThXRURUTS4u'], ['For more information: 343-478-0196 ext. 214', 'darcy.whalen@iipct.com']], 'note': None, 'img': None, 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid032uX8vv9dxGBUR9DPfasUVcTDmQqkbs8nayuQDrzTqkxWeBF4AHmdpDu4GN2vd8yxl'},
 {'i': 112, 'id': 'u1605107504955282', 'date': '2026-05-04', 'cat': 'Health', 'show': 'event-archive', 'head': 'Hypertension Awareness Week – Blood Pressure Clinics', 'paras': [['Did you know high blood pressure often has no symptoms but can lead to serious health concerns like heart disease and stroke?'], ['Join us during Hypertension Awareness Week for a quick and easy blood pressure check and learn simple ways to support your heart health and overall wellness.'], ['Clinic Dates & Locations:', '• Bancroft Clinic – May 12 | 10:00am–2:00pm', '• Tyendinaga Clinic – May 12 | 9:00am–3:30pm', '• Kingston Clinic – May 13 | 9:00am–6:00pm'], ['Bonus: Attend a clinic for a chance to WIN an Apple Watch!'], ['Please note:', 'These clinics are for rostered patients only. You must have a Primary Care Provider (Physician or Nurse Practitioner) with IIPCT to book an appointment.'], ['To book or learn more, call 343-478-0196']], 'note': None, 'img': ('news/2026-05-04-hypertension-awareness-week-blood-pressure-clini.jpg', 640, 828, 'news/2026-05-04-hypertension-awareness-week-blood-pressure-clini-full.jpg', 'Flyer: Hypertension Awareness Week – Blood Pressure Clinics', 'images/2026-05-04_1201_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0cf1BpkBH5M4PxBoKQyMwVBxroWywtqa2tvKwWMABB6A8ZTcJ9xiXHBnqzcu62AbCl'},
 {'i': 118, 'id': 'u1595667692565930', 'date': '2026-04-24', 'cat': 'Health', 'show': 'event-archive', 'head': 'Community Cancer Screenings – Coming to Our Community', 'paras': [['Did you know FREE cancer screenings are available for those without a family doctor or nurse practitioner?'], ['We’re proud to be hosting clinics through the Indigenous Interprofessional Primary Care Team right here in our community:'], ['Tyendinaga Clinic', 'Tuesday, May 5', '4:30 – 7:00 p.m.', '45 Meadow Drive, Tyendinaga'], ['Kingston Clinic', 'Tuesday, May 26', '4:30 – 7:00 p.m.', '730 Front Rd, Kingston'], ['To book: 343-478-0196 Press 2, ext 208', 'tracy.keith@iipct.com'], ['Diabetes screening will also be available at these clinics!'], ['You may be eligible for cervical screening if you:', '• Are age 25–69', '• Have not had a screening in the last 5 years', '• Have a cervix', '• Do NOT have a family doctor or nurse practitioner']], 'note': None, 'img': None, 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0ruqLUNv5braBA6LYEw4jsDBEhyeycfG7gQUZ1rHf8E2D8XmRNuazUsZRHV953ot5l'},
 {'i': 121, 'id': 'u1592217149577651', 'date': '2026-04-20', 'cat': 'Health', 'show': 'event-archive', 'head': 'Free Hearing Screening Clinic – Tyendinaga', 'paras': [['Join the Indigenous Interprofessional Primary Care Team in partnership with Canadian Hearing Services for a FREE Hearing Clinic!'], ['Wednesday, April 29', '10:00 a.m. – 3:00 p.m.', '14 York Road, Unit #4, Shannonville, ON'], ['Services available:', '• Hearing loss screening', '• Ear wax checks', '• Information and support'], ['Appointments are in 30-minute time slots', 'Valid health card required'], ['To book your appointment, please call: 343-478-0196 ext. 127']], 'note': None, 'img': ('news/2026-04-20-free-hearing-screening-clinic-tyendinaga.jpg', 640, 828, 'news/2026-04-20-free-hearing-screening-clinic-tyendinaga-full.jpg', 'Flyer: Free Hearing Screening Clinic – Tyendinaga', 'images/2026-04-20_1404_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid037CQiuZYusJQtkyH4tsnNNBDa161tVT1pjKHFKXVUzYaNSTiUeMqdfiLEay7wFsmWl'},
 {'i': 122, 'id': 'u1589432643189435', 'date': '2026-04-17', 'cat': 'Announcement', 'show': 'event-archive', 'head': 'Caregiver Night Out', 'paras': [['Are you a caregiver—or have you been one in the past? This evening is for you.'], ['Join us for a relaxing and supportive night where you can connect with others, enjoy a warm meal, and take time for yourself.'], ['What to expect:', '• Chili & a bun', '• Learn how to make relaxing shower steamers', '• A chance to unwind, connect, and recharge'], ['Where: 14 York Road, Unit 4, Shannonville', 'When: Thursday, May 7th', 'Time: 5:00 – 7:00 PM'], ['This event is open to IIPCT rostered clients and their immediate families, as well as Indigenous community members on and off territory.'], ['Scan the QR code on the poster to register!'], ['For more information, contact Shelley Loft at shelley.loft@iipct.com or 343-478-0196 ext. 115.'], ['Come take a well-deserved break—you deserve it.']], 'note': None, 'img': ('news/2026-04-17-caregiver-night-out.jpg', 640, 828, 'news/2026-04-17-caregiver-night-out-full.jpg', 'Flyer: Caregiver Night Out', 'images/2026-04-17_1000_1.jpg'), 'fb': 'https://www.facebook.com/IIPCT.TMT/posts/pfbid0ZjHrwoKWPaiLkX9JJwcPKyp1EeTKrnC1jYzmQzW8MgrXrT7MtYRvaW6xvm1ptDLHl'},
